import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/ContextualCorrelatesOfSynonymy.html","title":"ContextualCorrelatesOfSynonymy","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.49,"words":447},"filePathRelative":"ContextualCorrelatesOfSynonymy.md"}`),a={name:`ContextualCorrelatesOfSynonymy.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="contextualcorrelatesofsynonymy" tabindex="-1"><a class="header-anchor" href="#contextualcorrelatesofsynonymy"><span>ContextualCorrelatesOfSynonymy</span></a></h1><p><a href="./論文.html">論文</a>, <a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a></p><p><a href="https://dl.acm.org/doi/abs/10.1145/365628.365657?download=true" target="_blank" rel="noopener noreferrer">Contextual correlates of synonymy - Communications of the ACM</a></p><p><a href="./分布仮説.html">分布仮説</a>の論文。</p><h2 id="提唱する仮説-単語aの文脈と単語bの文脈で共通の単語の割合いは、単語aとbの意味の類似度の関数である" tabindex="-1"><a class="header-anchor" href="#提唱する仮説-単語aの文脈と単語bの文脈で共通の単語の割合いは、単語aとbの意味の類似度の関数である"><span>提唱する仮説: 単語Aの文脈と単語Bの文脈で共通の単語の割合いは、単語AとBの意味の類似度の関数である</span></a></h2><p>同じ所が本の方でも抜き出されているな。synonymyは意味の類似度の事のよう。 synonymは類義語とか同義語みたいな意味だったかな？</p><p>この論文ではfirst-orderのassocicationで意味の類似度が示される(indicated)と仮定して進める。</p><p>morphemses: 形態素</p><h2 id="_4つのコンテキスト" tabindex="-1"><a class="header-anchor" href="#_4つのコンテキスト"><span>4つのコンテキスト</span></a></h2><p>4つのcontextというのが挙げられているが、これは後で実際に実験の詳細で説明される。</p><ol><li>sentenceの中の単語(content wordsだけじゃなくfunction wordsも含む）</li><li>sentenceの中でLorge Magazine Countによる特定の範囲の頻度の全てのcontent word</li><li>各sentenceで文法的な枠組みでもっともtheme wordと近い全てのcontent word</li><li>そのthemeと関連がもっとも深いと判断された全ての単語</li></ol><p>Lorge Magazine Countは雑誌を対象にした常用語の出現頻度調査らしい。</p><p>基本的にはコンテキストに関係無さそうな単語を排除していく事でどんどん相関は増していく。</p><h2 id="実験手順" tabindex="-1"><a class="header-anchor" href="#実験手順"><span>実験手順</span></a></h2><p>実験手順もなんか複雑だな。</p><p>最初は以下のように書いてあるが、</p><ul><li>65ペアを作る(どうやって？)</li><li>全スリップを渡してそれを類似度順にならべて、その後0.0から4.0までのスコアをつけてもらう</li></ul><p>その後に二つのグループの話が出てきて上との関係が良くわからない。</p><p>Group I</p><ul><li>15被験者</li><li>2週間の間をあけて2つのセッションに参加</li><li>最初のセッションは48ペアについて類似度を判定してもらう、この48のうち36ペアは65ペアに含まれる</li><li>次のセッションでは65ペアについて類似度を判定してもらう</li></ul><p>product moment correlationは積率相関係数でピアオンの相関係数の事っぽい。</p><p>この36ペアについて、最初と次のセッションの間のproduct moment correlationを求める事で、 intra subject reliabilityが計算出来る、といっている。</p><p>このsubjectは被験者の意味か。時間をあけて、他のに混ぜてもどのくらいこの類似度は同じ値(一貫している)か？という事だな。</p><p>Group IIは二番目のセッションだけやってもらった。 Group Iとはとても一致していたので2セッションに分けた弊害はあまりなさそう、という事か。</p><p>Generation of the Corpusのパラグラフでは65のtheme pairsには48の名詞があると言っている。 ペアには重複する単語があるので48個という事かな。</p><p>AとBはテーマペアがそれぞれになるように適当に選んだのかな。 AとBで別の被験者を使って例文を作ってもらう。 AとBで分けたのは同じ人であるがゆえの疑似相関を避けたかったとか。</p><h2 id="levelingの影響" tabindex="-1"><a class="header-anchor" href="#levelingの影響"><span>levelingの影響</span></a></h2><p>walksをwalkに統一したり、という操作をしても、単にカーブが並行移動しただけで形状は変わらない、と結論づけている。</p><h2 id="inference-power" tabindex="-1"><a class="header-anchor" href="#inference-power"><span>Inference Power</span></a></h2><p>似てないかどうかを判定している（synonymyがless than 3.0かどうか）。</p><p>帰無仮説としては「似てない」で、 これを誤ってrejectしてしまう（似ていると判定してしまう）ものをType I Errorとしている。</p><p>Type I Error: false positive</p><h2 id="演習2-3-原論文から解き明かす生成ai" tabindex="-1"><a class="header-anchor" href="#演習2-3-原論文から解き明かす生成ai"><span>演習2.3 (原論文から解き明かす生成AI)</span></a></h2><p><img src="/RandomThoughts/assets/0000-o-h6UYza.png" alt="imgs/DistHypo/0000.png"></p><h2 id="実験の設定-freq考慮" tabindex="-1"><a class="header-anchor" href="#実験の設定-freq考慮"><span>実験の設定: Freq考慮</span></a></h2><p><img src="/RandomThoughts/assets/0001-CSFtgveK.png" alt="imgs/DistHypo/0001.png"></p><h2 id="実験の設定-gramatical" tabindex="-1"><a class="header-anchor" href="#実験の設定-gramatical"><span>実験の設定: Gramatical</span></a></h2><p><img src="/RandomThoughts/assets/0002-BuOZ1H5C.png" alt="imgs/DistHypo/0002.png"></p><h2 id="実験の設定-association" tabindex="-1"><a class="header-anchor" href="#実験の設定-association"><span>実験の設定: Association</span></a></h2><p><img src="/RandomThoughts/assets/0003-DTwNjG3N.png" alt="imgs/DistHypo/0003.png"></p>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};